{
  "name": "prod-guard",
  "version": "0.3.2",
  "description": "Confirm production kubectl/helm/IAM mutations before they run (also inside aws-vault exec), require an explicit kube context, and hand interactive aws-vault commands to you",
  "author": {
    "name": "blackironj"
  },
  "userConfig": {
    "prodContexts": {
      "type": "string",
      "title": "Production contexts",
      "description": "Comma-separated kube contexts whose mutating kubectl/helm commands need your confirmation.",
      "default": "prod"
    },
    "requireContext": {
      "type": "boolean",
      "title": "Require --context",
      "description": "Refuse mutating kubectl commands that do not name an explicit --context.",
      "default": true
    }
  }
}
